INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am3_l41',3,9,41,'Illusions of Pastoral Peace','宁静田园生活的遐想','名词/形容词 + 过去分词构成的合成形容词(city-bred)、be under the illusion that(that 同位语从句)、superior to / compare with(比较搭配)、do without / make do with、at the mere mention of·draw to a close·beyond me 固定搭配(原创承载 NCE3 第三册 L41 考点·无需净化:铁杆城里人反驳''乡村生活更美好''的错觉,历数城市之便·观点议论文;第三册无 KS 练习页,考点由课文结构自取;美式化 theater/stores/downtown)','宁静的乡村生活从来没有吸引过我。我生在城市、长在城市,总把乡村看作透过车窗一晃而过的风景,或偶尔周末去逛一逛的地方。我的朋友大多住在城里,可他们一提起乡村,就立刻欣喜若狂。尽管他们大讲宁静生活的种种好处,真正搬去乡下住的却只有一个,而且不到半年就搬回了城里。即便是他,至今仍抱着一种错觉,以为乡村生活总归比城市生活优越。他没完没了地念叨那些友善的邻居、清新的空气和悠闲的生活节奏。他坚持说,没有什么能比得上清晨的第一声鸡鸣、小鸟的啁啾。可这幅田园诗般的景象,不过是画面的一角。我的朋友从不提电视机前漫长而寂寞的冬夜——电视几乎是那里唯一的娱乐;也不提本地商店货品单调,更不提那些每天不得不从乡下赶进城上班的倒霉人。人们为什么甘愿为住在乡下这一可疑的特权,忍受每天四小时的通勤,我实在想不通。要是你能舍弃乡间那点田园乐趣,你会发现城市能给你生活中最好的东西。你根本不必跋涉几英里去看朋友,他们就住在附近,随时可以闲聊几句,或一起过个热闹的夜晚。我在乡下的一些熟人,每年进城一两次去看场戏,当作难得的享受。对他们来说,这是件大事,得精心筹划;戏快散场时,他们又开始担心能不能赶上末班车回家。城里人从不为这种事发愁。最新的展览、电影、戏剧,不过是一段短短的公交车程。购物也永远是种乐趣,品种繁多,你从不必用二等货来凑合。城市里也不乏美景:静谧的周末,冷清的市中心街道,少有什么能比这更让人心安。城里人明明享受着这一切异域般的舒适,却固执地声称自己更愿住在乡下——这在我一直是个谜。','{"q":"Listen and answer — What particular anxiety spoils the country dweller''s visit to the theater?","options":["Whether they will catch the last train home","Whether the tickets are sold out","Whether the play is any good","Whether it will rain"],"answer_index":0}'::jsonb,'{"title":"合成形容词 / be under the illusion that / superior to / do without · make do with","intro":"①名词/形容词 + 过去分词可构成合成形容词:city-bred(城里长大的)、well-mannered、hand-written。②be under the illusion that … 里 that 引导同位语从句,说明 illusion 的内容。③superior to(优于,用 to 不用 than);compare with(与…相比)。④do without(没有…也行);make do with(用…凑合、将就)。⑤固定搭配:at the mere mention of(一提到)、draw to a close(接近尾声)、beyond me(我无法理解)。","table":{"headers":["用法","意思","例子"],"rows":[["名词/形容词 + 过去分词","合成形容词","city-bred / hand-written"],["be under the illusion that","抱有…的错觉","the illusion that country life is better"],["superior to / compare with","优于 / 与…相比","superior to city life"],["do without / make do with","没有…也行 / 凑合用","make do with second best"]]},"specialRules":[{"rule":"superior 后用介词 to,不用 than;superior to(优于)、inferior to(劣于)。","mark":"superior to"},{"rule":"do without=没有…也能过;make do with=(在缺更好的情况下)用…凑合、将就。两个短语意思不同。","mark":"do without / make do with"},{"rule":"美式:theater(英式 theatre)、store(英式 shop)、downtown(英式 city centre)、movie(英式 film)。本课已按美语写。","mark":"theater / downtown"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l41',1,NULL,'The quiet life of the country has never appealed to me. City born and city bred, I have always thought of the countryside as something you glimpse through a car window, or somewhere you visit for a weekend now and then. Most of my friends live in the city, yet they go into raptures at the mere mention of the country.','宁静的乡村生活从来没有吸引过我。我生在城市、长在城市,总把乡村看作透过车窗一晃而过的风景,或偶尔周末去逛一逛的地方。我的朋友大多住在城里,可他们一提起乡村,就立刻欣喜若狂。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l41',2,NULL,'Though they extol the virtues of the peaceful life, only one of them has ever actually moved there, and he was back in town within six months. Even he still lives under the illusion that country life is somehow superior to city life. He is forever talking about the friendly neighbors, the clean air, and the gentle pace of living. Nothing, he insists, can compare with the crow of a rooster and the twitter of birds at dawn.','尽管他们大讲宁静生活的种种好处,真正搬去乡下住的却只有一个,而且不到半年就搬回了城里。即便是他,至今仍抱着一种错觉,以为乡村生活总归比城市生活优越。他没完没了地念叨那些友善的邻居、清新的空气和悠闲的生活节奏。他坚持说,没有什么能比得上清晨的第一声鸡鸣、小鸟的啁啾。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l41',3,NULL,'But this idyllic, pastoral picture is only part of the story. My friend never mentions the long, friendless winter evenings in front of the TV — virtually the only form of entertainment — or the poor selection of goods in the local stores, or the unlucky people who must drive from the country into the city every day for work. Why anyone would tolerate a four-hour commute for the dubious privilege of living in the country is beyond me.','可这幅田园诗般的景象,不过是画面的一角。我的朋友从不提电视机前漫长而寂寞的冬夜——电视几乎是那里唯一的娱乐;也不提本地商店货品单调,更不提那些每天不得不从乡下赶进城上班的倒霉人。人们为什么甘愿为住在乡下这一可疑的特权,忍受每天四小时的通勤,我实在想不通。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l41',4,NULL,'If you can do without the few pastoral pleasures of the country, you will find that the city offers the best that life can give. You never have to travel miles to see your friends; they live nearby and are always available for an informal chat or an evening out. Some of my country acquaintances come into town once or twice a year to visit the theater as a special treat. For them this is a major operation that involves careful planning, and as the play draws to a close, they begin to wonder whether they will catch the last train home.','要是你能舍弃乡间那点田园乐趣,你会发现城市能给你生活中最好的东西。你根本不必跋涉几英里去看朋友,他们就住在附近,随时可以闲聊几句,或一起过个热闹的夜晚。我在乡下的一些熟人,每年进城一两次去看场戏,当作难得的享受。对他们来说,这是件大事,得精心筹划;戏快散场时,他们又开始担心能不能赶上末班车回家。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l41',5,NULL,'The city dweller never feels anxieties of this sort. The latest exhibitions, movies, and plays are only a short bus ride away, and shopping is always a pleasure, with so much variety that you never have to make do with second best. There is even beauty in the city: few things are more peaceful than deserted downtown streets on a quiet weekend. It has always been a mystery to me why city people, who obstinately claim they would rather live in the country, appreciate none of the exotic comforts around them.','城里人从不为这种事发愁。最新的展览、电影、戏剧,不过是一段短短的公交车程。购物也永远是种乐趣,品种繁多,你从不必用二等货来凑合。城市里也不乏美景:静谧的周末,冷清的市中心街道,少有什么能比这更让人心安。城里人明明享受着这一切异域般的舒适,却固执地声称自己更愿住在乡下——这在我一直是个谜。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
