INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l41','go into raptures','',NULL,'/ɡoʊ ˈɪntə ˈræptʃərz/','They go into raptures over the country.','他们一提乡村就欣喜若狂。','She went into raptures about the food.','她对那些食物赞不绝口。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l41','do without','',NULL,'/duː wɪˈðaʊt/','You can do without a few country pleasures.','少几样乡间乐趣你也过得去。','I can''t do without my morning coffee.','我离不开早晨那杯咖啡。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l41','draw to a close','',NULL,'/drɔː tə ə kloʊz/','As the play drew to a close, they left.','戏快散场时,他们走了。','The year is drawing to a close.','一年就要结束了。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l41','make do with','',NULL,'/meɪk duː wɪð/','You never have to make do with second best.','你从不必用二等货凑合。','We made do with what we had.','我们用手头有的东西将就了。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l41',5,'am3_l41_gp1','choice','{"stem":"\"City ___ and city bred, I love urban life.\"(\"在城里出生\":名词 + 过去分词,构成合成形容词)","options":["to bear","bear","born","bearing"],"answer_index":2,"stem_cn":"我生在城市、长在城市,热爱都市生活。","explanation_cn":"名词/形容词 + 过去分词构成合成形容词;city born=在城里出生的。✓ City born and city bred. ✗ bear / bearing / to bear:合成形容词用过去分词 born。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l41',5,'am3_l41_gp1','choice','{"stem":"\"He is a well-___ young man with fine manners.\"(well + 过去分词,\"有教养的\")","options":["mannered","manner","manners","mannering"],"answer_index":0,"stem_cn":"他是个很有教养的年轻人。","explanation_cn":"well + 过去分词 mannered,“有教养的”。✓ a well-mannered young man. ✗ manner(名词)/ manners / mannering:合成形容词用 mannered。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l41',5,'am3_l41_gp1','choice','{"stem":"\"She sent me a hand-___ letter.\"(hand + 过去分词,\"手写的\")","options":["writing","write","wrote","written"],"answer_index":3,"stem_cn":"她给我寄来一封手写的信。","explanation_cn":"hand + 过去分词 written,“手写的”。✓ a hand-written letter. ✗ write / writing / wrote:合成形容词用过去分词 written。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l41',5,'am3_l41_gp2','choice','{"stem":"\"He lives under the illusion ___ country life is better.\"(引导同位语从句,说明 illusion 的内容,用哪个)","options":["which","that","what","whether"],"answer_index":1,"stem_cn":"他抱着乡村生活更好的错觉。","explanation_cn":"be under the illusion that … 里,that 引导同位语从句,说明 illusion 的内容。✓ the illusion that country life is better. ✗ which / what / whether:同位语从句用 that。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l41',5,'am3_l41_gp2','choice','{"stem":"\"I was under the ___ that the shops would be open.\"(\"错觉、幻想\"用哪个名词)","options":["promise","question","decision","illusion"],"answer_index":3,"stem_cn":"我误以为商店会开着。","explanation_cn":"“错觉、幻想”用 illusion;be under the illusion。✓ under the illusion that the shops would be open. ✗ decision 决定;✗ promise 承诺;✗ question 问题——都不对。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l41',5,'am3_l41_gp2','choice','{"stem":"\"There is no ___ that hard work brings success.\"(\"毫无……,……是肯定的\":no ___ that,用哪个名词)","options":["chance","illusion","doubt","reason"],"answer_index":2,"stem_cn":"毫无疑问,努力会带来成功。","explanation_cn":"“毫无疑问”用 there is no doubt that。✓ There is no doubt that hard work brings success. ✗ illusion(错觉)/ chance / reason:“毫无疑问”用 doubt。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l41',5,'am3_l41_gp3','choice','{"stem":"\"He thinks country life is superior ___ city life.\"(superior ___ 用哪个介词)","options":["to","than","from","with"],"answer_index":0,"stem_cn":"他认为乡村生活优于城市生活。","explanation_cn":"superior 后用介词 to,不用 than。✓ superior to city life. ✗ than / from / with:superior 搭配 to。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l41',5,'am3_l41_gp3','choice','{"stem":"\"Nothing can compare ___ a sunrise over the fields.\"(compare ___,\"与…相比\")","options":["to about","of","at","with"],"answer_index":3,"stem_cn":"没什么能和田野上的日出相比。","explanation_cn":"compare with,“与…相比”。✓ Nothing can compare with a sunrise. ✗ to about / of / at:compare 搭配 with。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l41',5,'am3_l41_gp3','choice','{"stem":"\"This car is far ___ to the older model.\"(\"更优越的\"用哪个词)","options":["superior","well","more good","better than"],"answer_index":0,"stem_cn":"这辆车比旧款优越得多。","explanation_cn":"“更优越的”用 superior(本身含比较意义,后接 to)。✓ superior to the older model. ✗ better than(说法可以但此处考 superior)/ more good / well:用 superior。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l41',5,'am3_l41_gp4','choice','{"stem":"\"If you can do ___ a few country pleasures, the city is better.\"(do ___,\"没有…也行\")","options":["with","out","without","off"],"answer_index":2,"stem_cn":"要是你能舍弃几样乡间乐趣,城市更好。","explanation_cn":"do without,“没有…也行、舍弃”。✓ do without a few country pleasures. ✗ with / out / off:“没有…也行”用 do without。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l41',5,'am3_l41_gp4','choice','{"stem":"\"There is so much variety that you never make ___ with second best.\"(make ___ with,\"凑合用\")","options":["out","off","up","do"],"answer_index":3,"stem_cn":"品种繁多,你从不必用二等货凑合。","explanation_cn":"make do with,“(缺更好的)用…凑合”;这里填 do。✓ never make do with second best. ✗ up / out / off:凑合用 make do with。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l41',5,'am3_l41_gp4','choice','{"stem":"\"We had no coffee, so we had to make do ___ tea.\"(make do ___,\"用…将就\")","options":["for","with","of","without"],"answer_index":1,"stem_cn":"没有咖啡,我们只好用茶将就。","explanation_cn":"make do with,“用…将就”,介词是 with。✓ make do with tea. ✗ without / of / for:make do 搭配 with。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l41',5,'am3_l41_gp5','choice','{"stem":"\"They go into raptures at the mere ___ of the country.\"(at the mere ___ of,\"一提到\")","options":["sound","memory","mention","sight"],"answer_index":2,"stem_cn":"一提到乡村,他们就欣喜若狂。","explanation_cn":"at the mere mention of,“一提到…”。✓ at the mere mention of the country. ✗ memory / sound / sight:固定用 mention。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l41',5,'am3_l41_gp5','choice','{"stem":"\"As the play drew to a ___, they worried about the last train.\"(draw to a ___,\"接近尾声\")","options":["halt","close","rest","stop"],"answer_index":1,"stem_cn":"戏快演完时,他们担心赶不上末班车。","explanation_cn":"draw to a close,“接近尾声、结束”。✓ as the play drew to a close. ✗ stop / rest / halt:固定用 close。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l41',5,'am3_l41_gp5','choice','{"stem":"\"Why anyone tolerates that commute is ___ me.\"(\"我所无法理解的\":___ me,填介词)","options":["within","above","under","beyond"],"answer_index":3,"stem_cn":"谁能忍受那样的通勤,我实在想不通。","explanation_cn":"“我所无法理解的”用 beyond me。✓ Why anyone tolerates that is beyond me. ✗ above / under / within:“无法理解”用 beyond me。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l41',5,'am3_l41_gp6','choice','{"stem":"\"To praise something highly is to ___ it.\"(\"赞美、颂扬\"用哪个词)","options":["blame","extol","doubt","ignore"],"answer_index":1,"stem_cn":"高度赞美某事物。","explanation_cn":"高度赞美、颂扬是 extol。✓ extol the virtues of country life. ✗ blame 责怪;✗ ignore 忽视;✗ doubt 怀疑——都不对。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l41',5,'am3_l41_gp6','choice','{"stem":"\"Something uncertain and possibly not worth it is ___.\"(\"可疑的、靠不住的\"用哪个词)","options":["certain","precious","common","dubious"],"answer_index":3,"stem_cn":"靠不住、未必值得的。","explanation_cn":"靠不住、未必值得的是 dubious。✓ the dubious privilege. ✗ certain 确定;✗ precious 珍贵;✗ common 普通——都不对。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l41',5,'am3_l41_gp6','choice','{"stem":"\"To keep insisting stubbornly, refusing to change, is to act ___.\"(\"固执地\"用哪个词)","options":["gladly","obstinately","briefly","quietly"],"answer_index":1,"stem_cn":"固执己见、不肯改。","explanation_cn":"固执己见、不肯改是 obstinately。✓ obstinately claim they prefer the country. ✗ gladly 乐意;✗ quietly 安静;✗ briefly 简短——都不对。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l41',6,NULL,'choice','{"stem":"illusion 的意思是:","options":["幻想,错觉","证据","事实","命令"],"answer_index":0,"explanation_cn":"illusion = 幻想、错觉。✓ under the illusion that country life is better 抱着乡村更好的错觉。\n顺带记:事实 = fact;证据 = proof;命令 = order."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l41',6,NULL,'choice','{"stem":"pastoral 的意思是:","options":["现代的","田园的","工业的","城市的"],"answer_index":1,"explanation_cn":"pastoral = 田园的。✓ the few pastoral pleasures 那点田园乐趣。\n顺带记:城市的 = urban;工业的 = industrial;现代的 = modern."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l41',6,NULL,'choice','{"stem":"superior 的意思是:","options":["低劣的","相同的","廉价的","优越的,更好的"],"answer_index":3,"explanation_cn":"superior = 优越的、更好的。✓ superior to city life 优于城市生活。\n顺带记:低劣的 = inferior;相同的 = equal;廉价的 = cheap."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l41',6,NULL,'choice','{"stem":"privilege 的意思是:","options":["义务","特权,难得的荣幸","惩罚","困难"],"answer_index":1,"explanation_cn":"privilege = 特权、难得的荣幸。✓ the dubious privilege 可疑的特权。\n顺带记:义务 = duty;惩罚 = punishment;困难 = difficulty."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l41',6,NULL,'choice','{"stem":"dweller 的意思是:","options":["建造者","游客","居住者","邻居"],"answer_index":2,"explanation_cn":"dweller = 居住者。✓ the city dweller 城里人。\n顺带记:游客 = tourist;建造者 = builder;邻居 = neighbor."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l41',6,NULL,'choice','{"stem":"exotic 的意思是:","options":["普通的","古老的","本地的","外来的,异国情调的"],"answer_index":3,"explanation_cn":"exotic = 外来的、异国情调的。✓ the exotic comforts 异域般的舒适。\n顺带记:本地的 = local;普通的 = ordinary;古老的 = ancient."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l41',7,NULL,'cloze','{"stem":"第 1 空","context":"The quiet life of the country has never appealed to me. City born and city ___1___, I love the city. My friends extol country life and live under the ___2___ that it is superior ___3___ city life. But if you can do ___4___ a few pastoral pleasures, the city offers far more.","blank_no":1,"options":["bred","breed","breeding","breeds"],"answer_index":0,"explanation_cn":"名词 + 过去分词构成合成形容词;city bred=在城里长大的。✓ City born and city bred."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l41',7,NULL,'cloze','{"stem":"第 2 空","context":"The quiet life of the country has never appealed to me. City born and city ___1___, I love the city. My friends extol country life and live under the ___2___ that it is superior ___3___ city life. But if you can do ___4___ a few pastoral pleasures, the city offers far more.","blank_no":2,"options":["illusion","fact","proof","order"],"answer_index":0,"explanation_cn":"“错觉、幻想”用 illusion;be under the illusion that。✓ live under the illusion that it is superior."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l41',7,NULL,'cloze','{"stem":"第 3 空","context":"The quiet life of the country has never appealed to me. City born and city ___1___, I love the city. My friends extol country life and live under the ___2___ that it is superior ___3___ city life. But if you can do ___4___ a few pastoral pleasures, the city offers far more.","blank_no":3,"options":["to","than","from","with"],"answer_index":0,"explanation_cn":"superior 后用介词 to。✓ superior to city life."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l41',7,NULL,'cloze','{"stem":"第 4 空","context":"The quiet life of the country has never appealed to me. City born and city ___1___, I love the city. My friends extol country life and live under the ___2___ that it is superior ___3___ city life. But if you can do ___4___ a few pastoral pleasures, the city offers far more.","blank_no":4,"options":["without","with","out","off"],"answer_index":0,"explanation_cn":"do without,“没有…也行、舍弃”。✓ if you can do without a few pastoral pleasures."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l41',8,NULL,'choice','{"stem":"How does the writer feel about country life?","options":["He grew up there","He loves it deeply","He plans to move there","It has never appealed to him"],"answer_index":3,"explanation_cn":"课文说 The quiet life of the country has never appealed to me——乡村生活从没吸引过他。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l41',8,NULL,'choice','{"stem":"What happened to the one friend who moved to the country?","options":["He stayed there happily","He was back in town within six months","He became a farmer","He never left"],"answer_index":1,"explanation_cn":"课文说 only one of them has ever actually moved there, and he was back in town within six months——唯一搬去的那位不到半年就搬回了城里。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l41',8,NULL,'choice','{"stem":"According to the writer, why is the city better for seeing friends?","options":["City friends are richer","The country has no phones","Friends live nearby and are always available","No one visits the country"],"answer_index":2,"explanation_cn":"课文说 You never have to travel miles to see your friends; they live nearby——城里朋友就住在附近,随时能见。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l41',9,NULL,'choice','{"stem":"你想说\"他抱着乡村生活更好的错觉\"(be under the illusion that):","options":["He is under the illusion that country life is better.","He is under the illusion which country life is better.","He is under the illusion what country life is better.","He is under illusion that country life is better."],"answer_index":0,"explanation_cn":"be under the illusion that … 里 that 引导同位语从句,说明 illusion 的内容。✓ He is under the illusion that country life is better. 场合:说某人抱着某种错觉。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l41',9,NULL,'choice','{"stem":"你想说\"他认为乡村生活优于城市生活\"(superior to):","options":["He thinks country life is more superior than city life.","He thinks country life is superior than city life.","He thinks country life is superior to city life.","He thinks country life is superior from city life."],"answer_index":2,"explanation_cn":"superior 后用介词 to,不用 than、也不加 more。✓ He thinks country life is superior to city life. 场合:说甲优于乙。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l41',9,NULL,'choice','{"stem":"你想说\"要是你能舍弃几样乡间乐趣\"(do without):","options":["If you can make without a few country pleasures, the city is better.","If you can do with out a few country pleasures, the city is better.","If you can do without of a few country pleasures, the city is better.","If you can do without a few country pleasures, the city is better."],"answer_index":3,"explanation_cn":"do without,“没有…也能过、舍弃”。✓ If you can do without a few country pleasures, the city is better. 场合:说少了某些东西也无妨。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l41',10,NULL,'choice','{"stem":"illusion 的意思是:","options":["命令","幻想,错觉","证据","事实"],"answer_index":1,"explanation_cn":"illusion = 幻想、错觉。✓ under the illusion that country life is better."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l41',10,NULL,'choice','{"stem":"exotic 的意思是:","options":["本地的","古老的","普通的","外来的,异国情调的"],"answer_index":3,"explanation_cn":"exotic = 外来的、异国情调的。✓ the exotic comforts around them."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l41',10,NULL,'choice','{"stem":"\"He lives under the illusion ___ country life is better.\"(引导同位语从句用哪个)","options":["which","whether","that","what"],"answer_index":2,"stem_cn":"他抱着乡村生活更好的错觉。","explanation_cn":"be under the illusion that … 里,that 引导同位语从句。✓ the illusion that country life is better. ✗ which / what / whether:同位语从句用 that。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l41',10,NULL,'choice','{"stem":"\"He thinks country life is superior ___ city life.\"(superior ___ 用哪个介词)","options":["to","with","from","than"],"answer_index":0,"stem_cn":"他认为乡村生活优于城市生活。","explanation_cn":"superior 后用介词 to。✓ superior to city life. ✗ than / from / with:superior 搭配 to。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l41',10,NULL,'choice','{"stem":"\"go into raptures\" 的意思是:","options":["沉沉睡去","陷入沉思","欣喜若狂","勃然大怒"],"answer_index":2,"explanation_cn":"go into raptures = 欣喜若狂。✓ go into raptures at the mere mention of the country 一提乡村就欣喜若狂。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l41',10,NULL,'choice','{"stem":"\"make do with\" 的意思是:","options":["完成任务","一起做","帮忙做","(将就)用…凑合"],"answer_index":3,"explanation_cn":"make do with = (缺更好的时候)用…凑合、将就。✓ make do with second best 用二等货凑合。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l41',10,NULL,'choice','{"stem":"Why does the writer think city dwellers are lucky?","options":["The country is dangerous","City air is cleaner","The best of exhibitions, movies, and shopping is only a short ride away","The country has no people"],"answer_index":2,"passage":"The quiet life of the country has never appealed to me. City born and city bred, I have always thought of the countryside as something you glimpse through a car window, or somewhere you visit for a weekend now and then. Most of my friends live in the city, yet they go into raptures at the mere mention of the country. Though they extol the virtues of the peaceful life, only one of them has ever actually moved there, and he was back in town within six months. Even he still lives under the illusion that country life is somehow superior to city life. He is forever talking about the friendly neighbors, the clean air, and the gentle pace of living. Nothing, he insists, can compare with the crow of a rooster and the twitter of birds at dawn. But this idyllic, pastoral picture is only part of the story. My friend never mentions the long, friendless winter evenings in front of the TV — virtually the only form of entertainment — or the poor selection of goods in the local stores, or the unlucky people who must drive from the country into the city every day for work. Why anyone would tolerate a four-hour commute for the dubious privilege of living in the country is beyond me. If you can do without the few pastoral pleasures of the country, you will find that the city offers the best that life can give. You never have to travel miles to see your friends; they live nearby and are always available for an informal chat or an evening out. Some of my country acquaintances come into town once or twice a year to visit the theater as a special treat. For them this is a major operation that involves careful planning, and as the play draws to a close, they begin to wonder whether they will catch the last train home. The city dweller never feels anxieties of this sort. The latest exhibitions, movies, and plays are only a short bus ride away, and shopping is always a pleasure, with so much variety that you never have to make do with second best. There is even beauty in the city: few things are more peaceful than deserted downtown streets on a quiet weekend. It has always been a mystery to me why city people, who obstinately claim they would rather live in the country, appreciate none of the exotic comforts around them.","explanation_cn":"课文说 The latest exhibitions, movies, and plays are only a short bus ride away——城里最好的展览、电影、购物都近在咫尺。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l41',10,NULL,'choice','{"stem":"What downside of country life does the writer''s friend never mention?","options":["The noise of tractors","The high cost of farms","The lack of sunshine","Long friendless winter evenings and a poor selection of goods"],"answer_index":3,"passage":"The quiet life of the country has never appealed to me. City born and city bred, I have always thought of the countryside as something you glimpse through a car window, or somewhere you visit for a weekend now and then. Most of my friends live in the city, yet they go into raptures at the mere mention of the country. Though they extol the virtues of the peaceful life, only one of them has ever actually moved there, and he was back in town within six months. Even he still lives under the illusion that country life is somehow superior to city life. He is forever talking about the friendly neighbors, the clean air, and the gentle pace of living. Nothing, he insists, can compare with the crow of a rooster and the twitter of birds at dawn. But this idyllic, pastoral picture is only part of the story. My friend never mentions the long, friendless winter evenings in front of the TV — virtually the only form of entertainment — or the poor selection of goods in the local stores, or the unlucky people who must drive from the country into the city every day for work. Why anyone would tolerate a four-hour commute for the dubious privilege of living in the country is beyond me. If you can do without the few pastoral pleasures of the country, you will find that the city offers the best that life can give. You never have to travel miles to see your friends; they live nearby and are always available for an informal chat or an evening out. Some of my country acquaintances come into town once or twice a year to visit the theater as a special treat. For them this is a major operation that involves careful planning, and as the play draws to a close, they begin to wonder whether they will catch the last train home. The city dweller never feels anxieties of this sort. The latest exhibitions, movies, and plays are only a short bus ride away, and shopping is always a pleasure, with so much variety that you never have to make do with second best. There is even beauty in the city: few things are more peaceful than deserted downtown streets on a quiet weekend. It has always been a mystery to me why city people, who obstinately claim they would rather live in the country, appreciate none of the exotic comforts around them.","explanation_cn":"课文说 My friend never mentions the long, friendless winter evenings…the poor selection of goods——朋友绝口不提乡下冬夜寂寞、货品单调。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l41',10,NULL,'choice','{"stem":"What special treat do the writer''s country acquaintances make once or twice a year?","options":["A trip abroad","A shopping spree at home","A trip into town to visit the theater","A boat ride"],"answer_index":2,"audio":"The quiet life of the country has never appealed to me. City born and city bred, I have always thought of the countryside as something you glimpse through a car window, or somewhere you visit for a weekend now and then. Most of my friends live in the city, yet they go into raptures at the mere mention of the country. Though they extol the virtues of the peaceful life, only one of them has ever actually moved there, and he was back in town within six months. Even he still lives under the illusion that country life is somehow superior to city life. He is forever talking about the friendly neighbors, the clean air, and the gentle pace of living. Nothing, he insists, can compare with the crow of a rooster and the twitter of birds at dawn. But this idyllic, pastoral picture is only part of the story. My friend never mentions the long, friendless winter evenings in front of the TV — virtually the only form of entertainment — or the poor selection of goods in the local stores, or the unlucky people who must drive from the country into the city every day for work. Why anyone would tolerate a four-hour commute for the dubious privilege of living in the country is beyond me. If you can do without the few pastoral pleasures of the country, you will find that the city offers the best that life can give. You never have to travel miles to see your friends; they live nearby and are always available for an informal chat or an evening out. Some of my country acquaintances come into town once or twice a year to visit the theater as a special treat. For them this is a major operation that involves careful planning, and as the play draws to a close, they begin to wonder whether they will catch the last train home. The city dweller never feels anxieties of this sort. The latest exhibitions, movies, and plays are only a short bus ride away, and shopping is always a pleasure, with so much variety that you never have to make do with second best. There is even beauty in the city: few things are more peaceful than deserted downtown streets on a quiet weekend. It has always been a mystery to me why city people, who obstinately claim they would rather live in the country, appreciate none of the exotic comforts around them.","explanation_cn":"课文说 Some of my country acquaintances come into town once or twice a year to visit the theater as a special treat——乡下熟人一年进城一两次看戏当享受。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l41',10,NULL,'choice','{"stem":"What worry do country people have as a city play ends?","options":["Whether their car will start","Whether they will catch the last train home","Whether it will rain","Whether the stores are open"],"answer_index":1,"audio":"The quiet life of the country has never appealed to me. City born and city bred, I have always thought of the countryside as something you glimpse through a car window, or somewhere you visit for a weekend now and then. Most of my friends live in the city, yet they go into raptures at the mere mention of the country. Though they extol the virtues of the peaceful life, only one of them has ever actually moved there, and he was back in town within six months. Even he still lives under the illusion that country life is somehow superior to city life. He is forever talking about the friendly neighbors, the clean air, and the gentle pace of living. Nothing, he insists, can compare with the crow of a rooster and the twitter of birds at dawn. But this idyllic, pastoral picture is only part of the story. My friend never mentions the long, friendless winter evenings in front of the TV — virtually the only form of entertainment — or the poor selection of goods in the local stores, or the unlucky people who must drive from the country into the city every day for work. Why anyone would tolerate a four-hour commute for the dubious privilege of living in the country is beyond me. If you can do without the few pastoral pleasures of the country, you will find that the city offers the best that life can give. You never have to travel miles to see your friends; they live nearby and are always available for an informal chat or an evening out. Some of my country acquaintances come into town once or twice a year to visit the theater as a special treat. For them this is a major operation that involves careful planning, and as the play draws to a close, they begin to wonder whether they will catch the last train home. The city dweller never feels anxieties of this sort. The latest exhibitions, movies, and plays are only a short bus ride away, and shopping is always a pleasure, with so much variety that you never have to make do with second best. There is even beauty in the city: few things are more peaceful than deserted downtown streets on a quiet weekend. It has always been a mystery to me why city people, who obstinately claim they would rather live in the country, appreciate none of the exotic comforts around them.","explanation_cn":"课文说 as the play draws to a close, they begin to wonder whether they will catch the last train home——戏快散场他们就担心赶不上末班车。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am3_l42',3,9,42,'Modern Cavemen','现代洞穴人','强调句 It is … that/who …、虚拟语气(与过去相反)+ 省略 if 的倒装(had not … been …)、现在分词短语修饰名词(a waterspout shooting down)、插入语(as it has come to be known / they found)、情态完成式 might/must/could have done(对过去的推测)(原创承载 NCE3 第三册 L42 考点·无需净化:洞穴探险科普——描写世界最深洞之一 Gouffre Berger 的下探·探险说明文;第三册无 KS 页,考点由课文结构自取;美式化 caving/colors)','洞穴勘查——或者说如今人们所熟知的“洞穴探险”——是一项比较新的运动。也许正是对独处的渴望,或是意外发现的机会,把人引向地下深处。要对一个洞穴探险者的动机作出令人满意的解释,是不可能的。对他来说,洞穴的那种奇特魅力,就像高山对登山者的魅力一样;它们唤起某种只能隐约体会的本能。探测真正深的洞穴,可不是星期天下午散步的人能胜任的。这类行动需要军事行动般的周密筹划和远见。有时得花整整八天来搭好绳梯、建立补给点,然后才能下到一个很深的洞里。这样的防范是必要的,因为无法预料洞穴探险者究竟会遇上什么样的困难。世界上已知最深的洞穴之一,是格勒诺布尔附近的高弗·伯杰洞,深达三千七百多英尺。这道巨大的陷坑,是一条地下暗流冲穿岩石的一道裂缝、慢慢冲蚀而成的。洞口高踞阿尔卑斯山的一处高原之上,宽仅约六英尺,很难被人察觉。要不是一位著名的法国洞穴探险家伯杰偶然发现了洞口,这个洞也许永远无人知晓。前不久,一支探险队下到了高弗·伯杰洞。钻过狭窄的洞口后,他们沿陡峭的洞壁往下爬,直到来到一条狭窄的通道。他们只能侧身沿通道慢慢挪动,有时蹚过浅溪,有时游过深潭。忽然,他们来到一道瀑布前,瀑布跌入洞底的一个地下湖。他们把装备装上一只充气橡皮艇,让水流载着他们渡到对岸,还穿上特制的橡胶服,以防冰冷的湖水。在远端,他们能听见一阵不断的轰鸣声,他们发现,那是一股从洞顶冲下的小水柱造成的。从岩石的一道裂隙中挤过去,探险者们来到一个巨大的洞穴,大得像座音乐厅。打开强光灯,他们看见一根根石笋——有的高达四十多英尺——像树干般拔地而起,去迎接从洞顶垂下的钟乳石。四周,一堆堆石灰石在彩虹般的各色光芒中闪烁。在洞穴那诡异的寂静里,唯一的声响,是从头顶高高的穹顶上不断滴落的水滴。','{"q":"Listen and answer — With what does the writer compare the Gouffre Berger?","options":["A pot-holers'' Everest","A quiet library","A crowded market","A wide desert"],"answer_index":0}'::jsonb,'{"title":"强调句 It is…that / 虚拟倒装 had not…been / 分词修饰名词 / 插入语 / might have done","intro":"①强调句 It is/was + 被强调部分 + that/who + 其余:It is the desire … that lures people down。②与过去事实相反的虚拟语气,若省略 if,要把 had 提到句首倒装:had not the entrance been spotted=if the entrance had not been spotted。③现在分词短语可放在名词后修饰它:a waterspout shooting down。④插入语补充说明,不影响主句:as it has come to be known;they found。⑤情态完成式 might/must/could have done,对过去作推测:might never have been discovered。","table":{"headers":["用法","意思","例子"],"rows":[["It is … that/who …","强调句","It is the desire that lures"],["had not … been …","省略 if 的虚拟倒装","had not the entrance been spotted"],["分词修饰名词 / 插入语","…着的… / 补充说明","a waterspout shooting down"],["might/must/could have done","对过去的推测","might never have been discovered"]]},"specialRules":[{"rule":"与过去相反的虚拟条件,省略 if 时把 had 提到主语前倒装:Had not the entrance been spotted, …(=If the entrance had not been spotted, …)。","mark":"had not … been"},{"rule":"情态动词 + have + 过去分词表示对过去的推测:might have(也许)、must have(一定)、could have(本可以却没)。","mark":"might/must/could have done"},{"rule":"美式:caving(英式 pot-holing)、color(英式 colour)、flashlight(英式 torch)。本课已按美语写。","mark":"caving / color"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l42',1,NULL,'Cave exploration, or caving, as it has come to be known, is a relatively new sport. Perhaps it is the desire for solitude, or the chance of making an unexpected discovery, that lures people down into the depths of the earth. It is impossible to give a satisfactory explanation for a caver''s motives. For him, caves hold the same peculiar fascination that high mountains hold for the climber; they arouse instincts that can only be dimly understood.','洞穴勘查——或者说如今人们所熟知的“洞穴探险”——是一项比较新的运动。也许正是对独处的渴望,或是意外发现的机会,把人引向地下深处。要对一个洞穴探险者的动机作出令人满意的解释,是不可能的。对他来说,洞穴的那种奇特魅力,就像高山对登山者的魅力一样;它们唤起某种只能隐约体会的本能。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l42',2,NULL,'Exploring really deep caves is not a task for the Sunday afternoon rambler. Such undertakings require the precise planning and foresight of a military operation. It can take as long as eight days to rig up rope ladders and set up supply bases before a descent can be made into a very deep cave. Precautions of this sort are necessary, for it is impossible to foretell the exact nature of the difficulties that will confront the caver.','探测真正深的洞穴,可不是星期天下午散步的人能胜任的。这类行动需要军事行动般的周密筹划和远见。有时得花整整八天来搭好绳梯、建立补给点,然后才能下到一个很深的洞里。这样的防范是必要的,因为无法预料洞穴探险者究竟会遇上什么样的困难。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l42',3,NULL,'One of the deepest known caves in the world is the Gouffre Berger, near Grenoble, which reaches a depth of more than 3,700 feet. This immense chasm was formed by an underground stream that tunneled a course through a flaw in the rock. The entrance, high on a plateau in the Alps, is only about six feet across, so it is barely noticeable. The cave might never have been discovered had not the entrance been spotted by a distinguished French caver named Berger.','世界上已知最深的洞穴之一,是格勒诺布尔附近的高弗·伯杰洞,深达三千七百多英尺。这道巨大的陷坑,是一条地下暗流冲穿岩石的一道裂缝、慢慢冲蚀而成的。洞口高踞阿尔卑斯山的一处高原之上,宽仅约六英尺,很难被人察觉。要不是一位著名的法国洞穴探险家伯杰偶然发现了洞口,这个洞也许永远无人知晓。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l42',4,NULL,'A team of cavers recently went down the Gouffre Berger. After entering the narrow gap, they climbed down the steep sides until they reached a narrow corridor. They had to edge their way along it, sometimes wading across shallow streams or swimming across deep pools. Suddenly they came to a waterfall that dropped into an underground lake. They loaded their gear onto an inflatable rubber dinghy and let the current carry them across, wearing special rubber suits to protect themselves from the icy water.','前不久,一支探险队下到了高弗·伯杰洞。钻过狭窄的洞口后,他们沿陡峭的洞壁往下爬,直到来到一条狭窄的通道。他们只能侧身沿通道慢慢挪动,有时蹚过浅溪,有时游过深潭。忽然,他们来到一道瀑布前,瀑布跌入洞底的一个地下湖。他们把装备装上一只充气橡皮艇,让水流载着他们渡到对岸,还穿上特制的橡胶服,以防冰冷的湖水。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l42',5,NULL,'At the far end they could hear an insistent booming sound, which they found was caused by a small waterspout shooting down from the roof. Squeezing through a cleft in the rock, the cavers arrived at an enormous cavern, as large as a concert hall. When they switched on their powerful lights, they saw great stalagmites — some of them over forty feet high — rising up like tree trunks to meet the stalactites hanging from the roof. All around, piles of limestone glistened in every color of the rainbow. In the eerie silence of the cavern, the only sound was water dripping from the high dome above them.','在远端,他们能听见一阵不断的轰鸣声,他们发现,那是一股从洞顶冲下的小水柱造成的。从岩石的一道裂隙中挤过去,探险者们来到一个巨大的洞穴,大得像座音乐厅。打开强光灯,他们看见一根根石笋——有的高达四十多英尺——像树干般拔地而起,去迎接从洞顶垂下的钟乳石。四周,一堆堆石灰石在彩虹般的各色光芒中闪烁。在洞穴那诡异的寂静里,唯一的声响,是从头顶高高的穹顶上不断滴落的水滴。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_words (lesson_id,word,ipa,pos,meaning_cn,example) VALUES ('am3_l42','solitude','/ˈsɑːlətuːd/','n','孤独,独处','the desire for solitude') ON CONFLICT (lesson_id,word) DO UPDATE SET ipa=EXCLUDED.ipa,pos=EXCLUDED.pos,meaning_cn=EXCLUDED.meaning_cn,example=EXCLUDED.example;
